<?php
defined('ABSPATH')||exit;
final class EduFlow_Phase6_Admin {
	public function register(){foreach(array('save_attendance','complete_lecture','notification_action','export_report')as$a){add_action('admin_post_eduflow_'.$a,array($this,$a));}}
	private static function guard($cap='eduflow_manage_classes'){if(!current_user_can($cap)){wp_die(esc_html__('You do not have permission.','eduflow-core'));}}
	public static function attendance(){self::guard();$lecture=absint($_GET['lecture']??0);?><div class="wrap eduflow-wrap"><h1>Attendance</h1><?php if($lecture){self::roster($lecture);return;}$range=EduFlow_Report_Service::range(sanitize_key($_GET['range']??'today'),$_GET['from']??'',$_GET['to']??'');if(is_wp_error($range)){$range=array(current_time('Y-m-d'),current_time('Y-m-d'));}$rows=EduFlow_Report_Service::attendance_rows($range[0],$range[1],0,50,(max(1,absint($_GET['paged']??1))-1)*50);self::filters('eduflow-attendance',$range);?><table class="widefat striped"><thead><tr><th>Attendance ID</th><th>Lecture</th><th>Date</th><th>Student</th><th>Batch</th><th>Teacher</th><th>Type</th><th>Status</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?php echo esc_html($r['canonical_id']);?></td><td><a href="<?php echo esc_url(add_query_arg(array('page'=>'eduflow-attendance','lecture'=>$r['lecture_db_id']),admin_url('admin.php')));?>"><?php echo esc_html($r['lecture_id']);?></a></td><td><?php echo esc_html($r['class_date']);?></td><td><?php echo esc_html($r['student']);?></td><td><?php echo esc_html($r['batch_name']);?></td><td><?php echo esc_html($r['teacher']);?></td><td><?php echo esc_html($r['class_type']);?></td><td><?php echo esc_html($r['attendance_status']);?></td></tr><?php endforeach;?></tbody></table></div><?php }
	private static function roster($lecture){$class=EduFlow_Class_Service::get($lecture);$rows=EduFlow_Attendance_Service::roster($lecture);if(!$class||is_wp_error($rows)){echo '<div class="notice notice-error"><p>'.esc_html(is_wp_error($rows)?$rows->get_error_message():'Lecture not found.').'</p></div></div>';return;}?><h2><?php echo esc_html($class['canonical_id']);?> — <?php echo esc_html($class['class_date']);?></h2><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="eduflow_save_attendance"><input type="hidden" name="lecture_id" value="<?php echo esc_attr($lecture);?>"><?php wp_nonce_field('eduflow_attendance_'.$lecture);?><p><button type="button" class="button" onclick="document.querySelectorAll('.ef-attendance').forEach(e=>e.value='present')">Mark All Present</button></p><table class="widefat striped"><thead><tr><th>Student</th><th>Status</th><th>Minutes</th><th>Notes</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?php echo esc_html($r['canonical_id'].' — '.$r['name']);?></td><td><select class="ef-attendance" name="attendance[<?php echo esc_attr($r['id']);?>][attendance_status]"><?php foreach(EduFlow_Attendance_Service::STUDENT_STATUSES as$s):?><option value="<?php echo esc_attr($s);?>" <?php selected($r['attendance_status'],$s);?>><?php echo esc_html(ucwords(str_replace('_',' ',$s)));?></option><?php endforeach;?></select></td><td><input type="number" min="0" name="attendance[<?php echo esc_attr($r['id']);?>][minutes_attended]" value="<?php echo esc_attr($r['minutes_attended']);?>"></td><td><input name="attendance[<?php echo esc_attr($r['id']);?>][notes]" value="<?php echo esc_attr($r['notes']);?>"></td></tr><?php endforeach;?></tbody></table><?php submit_button('Save Attendance');?></form><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="eduflow_complete_lecture"><input type="hidden" name="lecture_id" value="<?php echo esc_attr($lecture);?>"><?php wp_nonce_field('eduflow_complete_'.$lecture);?><textarea name="notes" placeholder="Class notes or issue"></textarea><?php submit_button('Mark Lecture Completed','secondary');?></form></div><?php }
	private static function filters($page,$range){?><form method="get"><input type="hidden" name="page" value="<?php echo esc_attr($page);?>"><select name="range"><?php foreach(array('today'=>'Today','yesterday'=>'Yesterday','last_7_days'=>'Last 7 Days','this_month'=>'This Month','last_month'=>'Last Month','custom'=>'Custom')as$k=>$v):?><option value="<?php echo esc_attr($k);?>" <?php selected($_GET['range']??'today',$k);?>><?php echo esc_html($v);?></option><?php endforeach;?></select><input type="date" name="from" value="<?php echo esc_attr($range[0]);?>"><input type="date" name="to" value="<?php echo esc_attr($range[1]);?>"><?php submit_button('Filter','secondary','',false);?></form><?php }
	public static function reports(){self::guard('eduflow_manage_reports');$range=EduFlow_Report_Service::range(sanitize_key($_GET['range']??'last_7_days'),$_GET['from']??'',$_GET['to']??'');if(is_wp_error($range)){$range=array(current_time('Y-m-d'),current_time('Y-m-d'));}$summary=EduFlow_Report_Service::summary($range[0],$range[1]);$workload=EduFlow_Report_Service::teacher_workload($range[0],$range[1]);$breakdowns=EduFlow_Report_Service::breakdowns($range[0],$range[1]);?><div class="wrap eduflow-wrap"><h1>Reports &amp; Analytics</h1><?php self::filters('eduflow-reports',$range);?><div class="eduflow-grid"><?php foreach($summary as$k=>$v):?><div class="eduflow-card"><h2><?php echo esc_html($v);?></h2><p><?php echo esc_html(ucwords(str_replace('_',' ',$k)));?></p></div><?php endforeach;?></div><?php foreach($breakdowns as$title=>$rows):?><h2><?php echo esc_html(ucwords(str_replace('_',' ',$title)));?></h2><?php self::data_table($rows);endforeach;?><h2>Teacher Workload</h2><?php self::data_table($workload);?><p><a class="button" href="<?php echo esc_url(wp_nonce_url(admin_url('admin-post.php?action=eduflow_export_report&from='.$range[0].'&to='.$range[1]),'eduflow_export_report'));?>">Export Attendance CSV</a></p></div><?php }
	private static function data_table($rows){?><table class="widefat striped"><thead><tr><?php foreach(array_keys($rows[0]??array('result'=>''))as$h):?><th><?php echo esc_html(ucwords(str_replace('_',' ',$h)));?></th><?php endforeach;?></tr></thead><tbody><?php foreach($rows as$r):?><tr><?php foreach($r as$v):?><td><?php echo esc_html($v);?></td><?php endforeach;?></tr><?php endforeach;if(!$rows):?><tr><td>No results.</td></tr><?php endif;?></tbody></table><?php }
	public static function notifications(){self::guard('eduflow_manage_reports');global$wpdb;$rows=$wpdb->get_results($wpdb->prepare("SELECT id,event_type,recipient_type,recipient_id,title,channels,notification_status,scheduled_at,sent_at,failure_reason FROM ".EduFlow_DB::table('notifications')." WHERE institute_id=%d ORDER BY id DESC LIMIT 100",EduFlow_Settings::institute_db_id()),ARRAY_A);?><div class="wrap"><h1>Notifications</h1><table class="widefat striped"><thead><tr><th>Event</th><th>Recipient</th><th>Title</th><th>Channels</th><th>Status</th><th>Failure</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?php echo esc_html($r['event_type']);?></td><td><?php echo esc_html($r['recipient_type'].' '.$r['recipient_id']);?></td><td><?php echo esc_html($r['title']);?></td><td><?php echo esc_html($r['channels']);?></td><td><?php echo esc_html($r['notification_status']);?></td><td><?php echo esc_html($r['failure_reason']);?></td><td><?php foreach(array('retry','cancel')as$a):?><a href="<?php echo esc_url(wp_nonce_url(admin_url('admin-post.php?action=eduflow_notification_action&record='.$r['id'].'&do='.$a),'eduflow_notification_'.$r['id']));?>"><?php echo esc_html(ucfirst($a));?></a> <?php endforeach;?></td></tr><?php endforeach;?></tbody></table></div><?php }
	public function save_attendance(){self::guard();$id=absint($_POST['lecture_id']??0);check_admin_referer('eduflow_attendance_'.$id);foreach((array)($_POST['attendance']??array())as$student=>$data){EduFlow_Attendance_Service::mark_student($id,absint($student),wp_unslash($data));}wp_safe_redirect(admin_url('admin.php?page=eduflow-attendance&lecture='.$id));exit;}
	public function complete_lecture(){self::guard();$id=absint($_POST['lecture_id']??0);check_admin_referer('eduflow_complete_'.$id);EduFlow_Attendance_Service::complete_lecture($id,wp_unslash($_POST['notes']??''));wp_safe_redirect(admin_url('admin.php?page=eduflow-attendance&lecture='.$id));exit;}
	public function notification_action(){self::guard('eduflow_manage_reports');$id=absint($_GET['record']??0);check_admin_referer('eduflow_notification_'.$id);'cancel'===sanitize_key($_GET['do']??'')?EduFlow_Notification_Service::cancel($id):EduFlow_Notification_Service::retry($id);wp_safe_redirect(admin_url('admin.php?page=eduflow-notifications'));exit;}
	public function export_report(){self::guard('eduflow_manage_reports');check_admin_referer('eduflow_export_report');$range=EduFlow_Report_Service::range('custom',$_GET['from']??'',$_GET['to']??'');if(is_wp_error($range)){wp_die(esc_html($range->get_error_message()));}$rows=EduFlow_Report_Service::attendance_rows($range[0],$range[1],0,1000,0);EduFlow_Audit_Service::log('report_exported','report','attendance',null,array('from'=>$range[0],'to'=>$range[1],'rows'=>count($rows)),EduFlow_Settings::institute_db_id());nocache_headers();header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="eduflow-attendance-'.$range[0].'-'.$range[1].'.csv"');$out=fopen('php://output','w');fputcsv($out,array('Attendance ID','Lecture ID','Date','Student ID','Student','Batch','Teacher','Class Type','Status','Minutes','Marked At'));foreach($rows as$r){unset($r['lecture_db_id']);fputcsv($out,array_values($r));}fclose($out);exit;}
}
